WITH parsed AS (SELECT id, host, level, status_code, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, context['region'] AS region, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT *, MAX(status_code) OVER (PARTITION BY level) AS level_max_status_code, LEAD(status_code, 1) OVER w_ordered AS next_status_code FROM parsed WINDOW w_ordered AS (PARTITION BY level ORDER BY duration_sec ASC, id ASC);
